  select id, '2026-2027', 1, 'Turneul 1', 'Noiembrie 2026' from public.categories where scope = 'regional' and code = 'U18M'
  on conflict (category_id, season, number) do nothing;
insert into public.groups (tournament_id, name, region, notes, sort_order)
  select t.id, 'Grupa A', null, null, 1
    from public.tournaments t join public.categories c on c.id = t.category_id
   where c.scope = 'regional' and c.code = 'U18M' and t.season = '2026-2027' and t.number = 1
  on conflict (tournament_id, name) do nothing;
insert into public.teams (club_id, category_id, name)
  select cl.id, c.id, 'ASC Lucky Dragons' from public.clubs cl, public.categories c
   where cl.name = 'ASC Lucky Dragons' and c.scope = 'regional' and c.code = 'U18M'
  on conflict (category_id, name) do nothing;
insert into public.group_teams (group_id, team_id)
  select gr.id, tm.id
    from public.groups gr
    join public.tournaments t on t.id = gr.tournament_id
    join public.categories c on c.id = t.category_id
    join public.teams tm on tm.category_id = c.id and tm.name = 'ASC Lucky Dragons'
   where c.scope = 'regional' and c.code = 'U18M' and t.season = '2026-2027' and t.number = 1 and gr.name = 'Grupa A'
  on conflict do nothing;
